import collections,json
def f(I):
    R,C=len(I),len(I[0])
    bgc=collections.Counter(x for r in I for x in r).most_common(1)[0][0]
    cnt=collections.defaultdict(list)
    for r in range(R):
        for c in range(C):
            if I[r][c]!=bgc: cnt[I[r][c]].append((r,c))
    O=[row[:] for row in I]
    for col,ps in cnt.items():
        rs=[p[0] for p in ps]; cs=[p[1] for p in ps]
        br0,br1=min(rs),max(rs); bc0,bc1=min(cs),max(cs)
        miss=[p for p in [(br0,bc0),(br0,bc1),(br1,bc0),(br1,bc1)] if p not in set(ps)][0]
        d=(miss[0]-br0,miss[1]-bc1)   # direction into missing corner quadrant
        nr,nc=miss[0]+d[0],miss[1]+d[1]
        while 0<=nr<R and 0<=nc<C:
            if O[nr][nc]==bgc: O[nr][nc]=col
            nr+=d[0]; nc+=d[1]
    return O
